<script setup>
import { ref } from 'vue'
import { PlusOutlined, AppstoreOutlined, UnorderedListOutlined, CheckOutlined, SearchOutlined } from '@ant-design/icons-vue'
import { storeToRefs } from 'pinia'
import { useTasks, statusLabels } from './composables/useTasks'
import { usePersistence } from './composables/usePersistence'
import { projects } from './stores/tasks'
import TaskCard from './components/TaskCard.vue'
import TaskForm from './components/TaskForm.vue'
usePersistence()
const {store,filtered,dueToday,overdueCount}=useTasks()
const {search,statusFilter,priorityFilter,projectFilter,sortBy,view}=storeToRefs(store)
const editor=ref(null)
const columns=[{key:'todo',label:'To do',subtitle:'A fresh start awaits',color:'#a8aaab'},{key:'progress',label:'In progress',subtitle:'Good things take focus',color:'#c39a5a'},{key:'done',label:'Completed',subtitle:'Look how far you’ve come',color:'#6a9274'}]
const today=new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(new Date())
</script>
<template><a-config-provider :theme="{token:{colorPrimary:'#356654',borderRadius:9,fontFamily:'Inter, -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif'}}"><div class="workspace"><aside class="sidebar"><a class="brand" href="#" @click.prevent="store.clearFilters()"><span>t.</span>taskly<span class="brand-star">✳</span></a><div class="workspace-name"><span class="workspace-avatar">N</span><div><strong>My workspace</strong><small>Personal space</small></div><span class="workspace-chevron">⌄</span></div><div class="sidebar-caption">WORKSPACE</div><button class="nav-button" :class="{selected:projectFilter==='all'}" @click="store.clearFilters()"><AppstoreOutlined/> All tasks <span>{{store.tasks.length}}</span></button><div class="sidebar-caption projects-caption">YOUR PROJECTS</div><button v-for="project in projects" :key="project" class="nav-button project-nav" :class="{selected:projectFilter===project}" @click="projectFilter=project"><span class="project-dot" :class="project.toLowerCase()"></span>{{project}}<span>{{store.tasks.filter(t=>t.project===project).length}}</span></button><div class="sidebar-bottom"><div class="little-note"><span>ONE STEP AT A TIME</span><h3>Less busy.<br>More meaningful.</h3><p>A little focus today goes a long way tomorrow.</p><div class="note-art">↗</div></div><div class="user"><a-avatar style="background:#e9d7bb;color:#6e5a40">NA</a-avatar><div><strong>Nurlan Askarov</strong><small>Student workspace</small></div><span class="online-dot"></span></div></div></aside><main><header class="topbar"><div>Workspace <span>/</span> <strong>Task manager</strong></div><div class="topbar-right"><span class="live-dot"></span> Saved on this device <a-avatar size="small" style="background:#356654">N</a-avatar></div></header><div class="page"><div class="page-heading"><div><div class="eyebrow">{{today}}</div><h1>Your day, in order<span>.</span></h1><p>A clear mind starts with a clear plan. Make room for what matters.</p></div><a-button type="primary" size="large" @click="editor.show()"><PlusOutlined/> Create task</a-button></div><a-alert v-if="store.storageError" :message="store.storageError" type="warning" show-icon style="margin-bottom:20px"/><section class="stats"><div><span class="stat-icon neutral"><UnorderedListOutlined/></span><div><small>Total tasks</small><strong>{{store.tasks.length.toString().padStart(2,'0')}}</strong></div><span class="stat-caption">a little plan, a lot of possibility</span></div><div><span class="stat-icon amber">◷</span><div><small>Due today</small><strong>{{dueToday.toString().padStart(2,'0')}}</strong></div><span class="stat-caption">{{overdueCount?`${overdueCount} overdue`:'one thing at a time'}}</span></div><div><span class="stat-icon green"><CheckOutlined/></span><div><small>Completed</small><strong>{{store.completed.toString().padStart(2,'0')}}</strong></div><div class="progress-wrap"><span>{{store.progress}}% of all tasks</span><a-progress :percent="store.progress" :show-info="false" size="small" stroke-color="#709179"/></div></div></section><section class="task-section"><div class="section-heading"><div><h2>{{projectFilter==='all'?'All tasks':projectFilter}} <a-tag>{{filtered.length}}</a-tag></h2><p>Your next steps, all in one place.</p></div><a-radio-group v-model:value="view" button-style="solid" size="small" aria-label="Task view"><a-radio-button value="board"><AppstoreOutlined/> Board</a-radio-button><a-radio-button value="list"><UnorderedListOutlined/> List</a-radio-button></a-radio-group></div><div class="toolbar"><a-input v-model:value="search" placeholder="Search tasks…" allow-clear aria-label="Search tasks" class="search"><template #prefix><SearchOutlined/></template></a-input><div class="filters"><a-select v-model:value="statusFilter" :options="[{value:'all',label:'All statuses'},...Object.entries(statusLabels).map(([value,label])=>({value,label}))]" aria-label="Filter status"/><a-select v-model:value="priorityFilter" :options="[{value:'all',label:'All priorities'},...['high','medium','low'].map(value=>({value,label:value[0].toUpperCase()+value.slice(1)}))]" aria-label="Filter priority"/><a-select v-model:value="sortBy" :options="[{value:'newest',label:'Newest first'},{value:'due',label:'Due date'},{value:'priority',label:'Priority'}]" aria-label="Sort tasks"/></div></div><div v-if="view==='board'" class="board"><section class="column" v-for="column in columns" :key="column.key"><div class="column-heading"><div><span class="column-dot" :style="{background:column.color}"></span><strong>{{column.label}}</strong><span class="column-count">{{filtered.filter(t=>t.status===column.key).length}}</span></div><button :aria-label="'Add '+column.label+' task'" @click="editor.show({status:column.key})">+</button></div><p class="column-subtitle">{{column.subtitle}}</p><TaskCard v-for="task in filtered.filter(t=>t.status===column.key)" :key="task.id" :task="task" @edit="editor.show($event)"/><div v-if="!filtered.some(t=>t.status===column.key)" class="column-empty"><span>◇</span><p>No {{column.label.toLowerCase()}} tasks</p></div><button class="add-task" @click="editor.show({status:column.key})"><PlusOutlined/> Add task</button></section></div><div v-else class="task-list"><TaskCard v-for="task in filtered" :key="task.id" :task="task" @edit="editor.show($event)"/><a-empty v-if="!filtered.length" description="No tasks match your filters"><a-button @click="store.clearFilters()">Clear filters</a-button></a-empty></div><div v-if="!filtered.length && view==='board'" class="no-results">No tasks to show. <a-button type="link" @click="store.clearFilters()">Clear filters</a-button></div></section><div class="bottom-note"><span>✳ A little progress, every day.</span><span>Vue 3 · Pinia · SIS 5</span></div></div></main></div><TaskForm ref="editor"/></a-config-provider></template>
